import{_ as r,C as l,o as c,c as o,a4 as a,j as s,E as i}from"./chunks/framework.BUqnS5H7.js";const _=JSON.parse('{"title":"事务与锁：综览","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/04-transaction-lock/chapter-01-overview.md","filePath":"mysql/04-transaction-lock/chapter-01-overview.md"}'),n={name:"mysql/04-transaction-lock/chapter-01-overview.md"},d={"data-src-line":"18","data-src-file":"mysql/04-transaction-lock/chapter-01-overview.md"};function m(v,t,h,p,f,y){const e=l("SvgDiagram");return c(),o("div",null,[t[0]||(t[0]=a('<h1 id="事务与锁-综览" tabindex="-1" data-src-line="1" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">事务与锁：综览 <a class="header-anchor" href="#事务与锁-综览" aria-label="Permalink to &quot;事务与锁：综览&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md"><p data-src-line="3" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">事务的隔离性不是靠单一机制实现的，而是「MVCC 管读、锁管写」两套机制分工配合。理解事务与锁，先建立这条主线，再看读和写各自走哪条路径。</p></blockquote><h2 id="_1-一条主线-隔离性-mvcc-锁" tabindex="-1" data-src-line="5" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">1. 一条主线：隔离性 = MVCC + 锁 <a class="header-anchor" href="#_1-一条主线-隔离性-mvcc-锁" aria-label="Permalink to &quot;1. 一条主线：隔离性 = MVCC + 锁&quot;">​</a></h2><p data-src-line="7" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">ACID 四项承诺里，隔离性（Isolation）要回答：两个事务并发读写同一份数据时，彼此能看到对方的哪些中间状态。InnoDB 用两套机制共同回答：</p><table tabindex="0"><thead data-src-line="9" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md"><tr data-src-line="9" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md"><th style="text-align:left;">机制</th><th style="text-align:left;">管什么</th><th style="text-align:left;">怎么管</th><th style="text-align:left;">载体</th></tr></thead><tbody data-src-line="11" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md"><tr data-src-line="11" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md"><td style="text-align:left;"><strong>MVCC</strong></td><td style="text-align:left;">读（快照读）</td><td style="text-align:left;">每行保留多个版本，读时按 Read View 挑一个可见版本，不加锁</td><td style="text-align:left;">Undo Log 版本链</td></tr><tr data-src-line="12" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md"><td style="text-align:left;"><strong>锁</strong></td><td style="text-align:left;">写，以及「要读最新值」的读</td><td style="text-align:left;">在索引记录上加行锁，阻塞冲突操作</td><td style="text-align:left;">Record / Gap / Next-Key Lock</td></tr></tbody></table><p data-src-line="14" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">为什么必须两套配合，单靠锁不够？锁只能挡住「正在改」，挡不住「改完提交了」。要挡住后者（可重复读），必须让读操作读到「事务开始那一刻的快照」而非「数据库最新状态」——这是 MVCC 的职责。反过来，写操作必须基于最新状态：两个事务若都基于同一份旧快照做 <code>balance = balance - 100</code>，会互相覆盖——这是锁的职责。</p><h2 id="_2-一条-sql-的路径分叉" tabindex="-1" data-src-line="16" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">2. 一条 SQL 的路径分叉 <a class="header-anchor" href="#_2-一条-sql-的路径分叉" aria-label="Permalink to &quot;2. 一条 SQL 的路径分叉&quot;">​</a></h2>',7)),s("p",d,[i(e,{src:"/mysql/04-transaction-lock-overview.svg",alt:"事务与锁：一条 SQL 的路径分叉"})]),t[1]||(t[1]=a('<p data-src-line="20" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">每一句 SQL 进来，先分「读」还是「写」，读再分两条：</p><ul data-src-line="22" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md"><li data-src-line="22" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md"><strong>快照读</strong>：普通 <code>SELECT</code>，走 MVCC，读历史可见版本，不加锁、不被写阻塞。</li><li data-src-line="23" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md"><strong>当前读</strong>：<code>SELECT ... FOR UPDATE</code> / <code>SELECT ... LOCK IN SHARE MODE</code>，绕过 MVCC，读最新版本并加锁。</li><li data-src-line="24" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md"><strong>写</strong>：<code>INSERT</code> / <code>UPDATE</code> / <code>DELETE</code>，本质先做一次当前读，再加锁。</li></ul><h2 id="_3-一笔并发读写里-三件事如何配合" tabindex="-1" data-src-line="26" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">3. 一笔并发读写里，三件事如何配合 <a class="header-anchor" href="#_3-一笔并发读写里-三件事如何配合" aria-label="Permalink to &quot;3. 一笔并发读写里，三件事如何配合&quot;">​</a></h2><p data-src-line="28" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">用 <a href="./chapter-02-transaction.html">事务与 MVCC</a> 开头的场景串一遍：</p><ol data-src-line="30" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md"><li data-src-line="30" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">事务 B <code>UPDATE</code>（写）：先做当前读拿到最新行、加行锁；同时把旧值写进 Undo Log，版本链多一节。</li><li data-src-line="31" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">事务 A 普通 <code>SELECT</code>（快照读）：走 MVCC，用 Read View 沿版本链判定可见版本，读到旧值 500，不加锁、不被 B 阻塞。</li><li data-src-line="32" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">事务 B <code>COMMIT</code>：释放行锁；它留下的 Undo 旧版本，等所有 Read View 都不再需要后由 Purge 清理。</li></ol><p data-src-line="34" data-src-file="mysql/04-transaction-lock/chapter-01-overview.md">这三步把三件事的关系讲清：<strong>Undo Log 提供历史版本（MVCC 的数据基础），Read View 判定该读哪个版本，锁保护写与写不冲突。</strong></p>',6))])}const k=r(n,[["render",m]]);export{_ as __pageData,k as default};
